import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"数据库安全与隐私保护","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/数据库与隐私保护.md","filePath":"安全方向/数据库与隐私保护.md","lastUpdated":1792430298000}'),i={name:"安全方向/数据库与隐私保护.md"};function d(o,t,h,n,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="数据库安全与隐私保护" tabindex="-1">数据库安全与隐私保护 <a class="header-anchor" href="#数据库安全与隐私保护" aria-label="Permalink to &quot;数据库安全与隐私保护&quot;">​</a></h1><blockquote><p>校内对应「数据库原理及安全」（第 4 学期，核心课，含课程设计）与「大数据安全与隐私保护」（主干课程）。数据是数字时代的核心资产，保护数据 = 保护一切。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>数据泄露是近年安全事件的重灾区，合规要求（等保、数据安全法）持续收紧；</li><li>数据库安全（权限、审计、加密）是安全运维的日常工作；</li><li>大数据时代，隐私保护技术（脱敏、差分隐私、加密计算）成为新兴热门方向。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/数据库.html">数据库</a>：SQL、事务、权限模型</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>数据库安全机制：用户权限、视图、审计日志、备份恢复</li><li>SQL 注入的防护（见 <a href="./Web安全.html">Web 安全</a>）</li><li>数据加密：透明加密（TDE）、字段级加密</li><li>隐私保护技术：数据脱敏、匿名化、差分隐私概念、多方安全计算/同态加密概念</li><li>大数据安全：数据生命周期管理、Hadoop/数据湖安全基线</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《数据库安全》/ 校内教材</td><td>教材</td><td>课程主线</td></tr><tr><td>《大数据安全与隐私保护》（相关专著）</td><td>拓展</td><td>方向深度阅读</td></tr><tr><td>OWASP SQL Injection Prevention Cheat Sheet</td><td>文档</td><td>防护权威参考（<a href="https://owasp.org/www-project-cheat-sheets/" target="_blank" rel="noreferrer">owasp.org</a>）</td></tr><tr><td>CMU 15-445（数据库实现）</td><td>公开课</td><td>理解数据库内部机制（<a href="https://15445.courses.cs.cmu.edu/" target="_blank" rel="noreferrer">15445.courses.cs.cmu.edu</a>）</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>把「权限最小化 + 审计」刻进习惯：任何数据库设计先想权限矩阵；</li><li>课程设计阶段主动加入「安全设计」元素（加密字段、审计表、脱敏接口）；</li><li>关注《数据安全法》《个人信息保护法》对技术方案的影响（见 <a href="./法律伦理与合规.html">法律伦理与合规</a>）。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>数据库原理及安全（第 4 学期，核心课，含课程设计）</li><li>大数据安全与隐私保护（主干课程）</li></ul>',14)])])}const b=a(i,[["render",d]]);export{_ as __pageData,b as default};
